insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (325, 'Afloat', 'Saunders, Kirli', NULL, 'From multi-award-winning Gunai author Kirli Saunders and Kate Greenaway Medal-winner Freya Blackwood comes Afloat. Against a backdrop of a changed environment, an Elder leads a child along the waterways, sharing her People’s knowledge and gathering community along the way. This uplifting and inspiring picture book uses the practice of weaving as a powerful metaphor for the honoring and teaching of First Nations wisdom, and the coming together of all people to survive, thrive, and create a more hopeful future.', 'verified', '325_afloat.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (326, 'Everything You Ever Wanted To Know About the Tooth Fairy (and Some Things You Didn''t)', 'Stewart, Briony', NULL, 'Every single minute, of every single day, a child somewhere loses a baby tooth. But what happens to all those teeth? They are collected by the tooth fairy, of course! Or the tooth fairies - because there is more than just one tooth fairy. In fact, there are millions! Like us, they are all different. And now there is an informative and fully illustrated guide that''s jam-packed with answers to every child''s tooth fairy questions, like: What do tooth fairies eat? Where do they live? How do they collect your tooth - and what on earth do they do with it? Find out everything there is to know about the magical (and sometimes just a little bit gross) world of the tooth fairy! ''This playful story for curious kids aged 5+ answers all their questions'' BOOKS+PUBLISHING', 'verified', '326_everything_you_ever_wanted_to_know_about_the_tooth_fairy_and.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (327, 'Grow Big, Little Seed', 'Nanayakkara, Bec', NULL, '2025 Winner of the CBCA Award for a New Illustrator. Grow Big, Little Seed is a tender, hopeful picture book about miscarriage and pregnancy after loss. Illustrated by the extraordinary papercut artist, Sarah Capon, it''s perfect for children aged 2 to 7, and any family celebrating their new baby. Exciting things were happening in Nina''s home. ''While we wait,'' said Mum, ''let''s plant a seed and watch it grow.'' When Nina plants a pumpkin seed, she imagines herself and a little sister playing in the leaves of a large pumpkin plant. Nina''s mum is pregnant and it seems that Nina''s dreams may soon come true. But despite Nina''s loving care, her seedling stops growing as her mother''s pregnancy ends early. As time goes by, her mother is pregnant again, and Nina finds the courage to plant another seed. This time, Nina''s seedling grows and grows, and her family embraces a joyful surprise with not one but two rainbow babies. The perfect picture book to share with any growing family.', 'verified', '327_grow_big_little_seed.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (328, 'Raymangirrbuy Dhawu When I Was a Little girl', 'Gatjawarrawuy Mununggurr, Kylie', NULL, 'A beautiful story of Kylie''s life on her grandmother''s Country, Raymangirr, a remote Yolŋu homeland in North East Arnhem Land in the Top End of Australia. This is a sweetly told story of the author''s experiences with her grandmother. From watching her grinding ochre and painting in the shade of a tree, to hunting for bush honey (guku) and painting ceremonial guku designs on their bodies (special permission was given to Kylie to paint this) and doing the guku dance to full-moon night fishing and cooking up a fish feast on the beach. Raymaŋgirrbuy dhäwu When I was a little girl developed through the author''s expressed interest in developing her skills in writing and illustrating. With the support of Gapuwiyak Culture and Arts Kylie developed the story with her mother and grandmother about the country, and cultural activities Gapuwiyak and in their Raymangirr homelands.', 'verified', '328_raymangirrbuy_dhawu_when_i_was_a_little_girl.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (329, 'How To Move a Zoo', 'Simpson, Kate', NULL, 'The true story of how at the beginning of the 20th century Jessie the elephant walked from Moore Park Zoo to her spacious new home in the Taronga Zoological Park. It was still dark when Mr Miller opened the gates of the old zoo, but he wasn''t scared because he wasn''t alone. He was with Jessie the elephant and together they were going to walk from Moore Park, through the city streets, to the ferry at Fort Macquarie. Jessie was moving to her spacious new home in the soon-to-be-opened Taronga Zoological Park. Jessie''s surprising journey was unlike any other and it brought a little warmth to the city on that brisk September morning in 1916. The incredible true story of Jessie the elephant from the bestselling author of Anzac Girl: The War Diaries of Alice Ross-King and the highly acclaimed illustrator of Anzac Biscuits.', 'verified', '329_how_to_move_a_zoo.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (330, 'Always Was Always Will Be', 'Muir, Fay and Lawson, Sue', NULL, '2025 CBCA Eve Pownall Award Winner. ''Each protest has been a stepping stone to the next battle...'' From the very first protest of January 26th as a Day of Mourning in 1938, to the Pilbara Strike of 1946, to the struggle for the right to vote and be counted; the fight for justice for First Nations people takes many forms. Always Was, Always Will Be takes a closer look at some of the iconic First Peoples protest movements of the last 200 years, celebrating the strength, wisdom, and bravery of Aboriginal and Torres Strait Islander people defending their land and asserting their right to self-determination through history.', 'verified', '330_always_was_always_will_be.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (331, 'Design and Building on Country', 'Page, Allison and Memmott, Paul', NULL, 'This ebook has a fixed layout and is best viewed on a widescreen, full-colour tablet. What do you need to know to prosper as a people for 65,000 years or more? Join designer and artist Alison Page alongside anthropologist and architect Paul Memmott as they share some of the incredible inventions created by the oldest continuing culture in the world. With striking colour illustrations from Archibald Prize winning artist Blak Douglas. The First Knowledges series for younger readers celebrates the wisdom and ingenuity of the First Peoples of this land. From baking the world''s first bread to expertly managing Country so that everything had a chance to flourish, these books provide children with the building blocks to better understand our history and look to the future with fresh eyes.', 'verified', '331_design_and_building_on_country.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (332, 'The Land Recalls You', 'Saunders, Kirli', NULL, 'Do not mourn the hands that raised you ... Do not weep for songs of land. Honouring the Stolen Generations, and all who''ve been taken, The Land Recalls You is a powerful story of returning, written with love and reverence by award-winning Gunai author Kirli Saunders (OAM) and illustrated by debut Bundjalung artists David and Noni Cragg.', 'verified', '332_the_land_recalls_you.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (333, 'The Garden of Broken Things', 'Blackwood, Freya', NULL, 'From award-winning creator Freya Blackwood comes a beautifully tender story about curiosity and the joy of listening. One day, curious Sadie follows a cat into the tangled vines behind the lonely house at Number 9, Ardent Street. Deep in the undergrowth, past all the twisted, rusted things, Sadie finds the cat sitting on the lap of a woman, bent with time and weariness. Sadie has found the Garden of Broken Things.', 'verified', '333_the_garden_of_broken_things.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (334, 'South with the Seabirds', 'McGeachin, Jess', NULL, 'The captivating true story of four remarkable scientists and their incredible journey to the sub-Antarctic, from CBCA award-winning author and illustrator Jess McGeachin. In 1959, four scientists travelled to an island at the edge of the world. They were greeted by giant seabirds, snorting seals and penguins as far as the eye could see. Their names were Hope Black, Mary Gilham, Susan Ingham and Isobel Bennett, and they were the first female scientists to join an Australian National Antarctic Research Expedition. Join their journey south and discover their incredible legacy.', 'verified', '334_south_with_the_seabirds.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (335, 'The Wobbly Bike', 'McCallum, Darren', NULL, 'The wonderful wobbles of learning to ride a bike, set amidst the vibrant colour and culture of Australia''s "top end". How do you fix a wobbly bike? Could it be the tyres, the terrain, or maybe it might be a new rider? A joyful, multi-layered story, celebrating the unique culture of Australia''s urban "top end", the precious roles of grandparents in families, the fact that kindness and encouragement, combined with practice, are the key to success, bound together with gentle humour... because laughter is always the best medicine.', 'verified', '335_the_wobbly_bike.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (336, 'Tigg and the Bandicoot Bushranger', 'French, Jackie', NULL, 'The year is 1859 and the goldfields are filled with diggers -- and danger! Orphaned twelve-year-old Tigg is the Bandicoot Bushranger, the youngest bushranger on the Ballarat goldfields in 1859. When a robbery goes wrong, Tigg must flee in disguise as one of the tens of thousands of Chinese men and boys braving heat, thirst, starvation and murderous attacks on the long road from Robe in South Australia to the goldfields in Victoria. But even further danger threatens. Who has offered a large sum of money for Tigg''s capture? And is the mysterious Henry Lau a friend or enemy? To be safe, Tigg must solve the greatest mystery of all. Who is Tigg? AWARDS CBCA Notable Book 2025', 'verified', '336_tigg_and_the_bandicoot_bushranger.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (337, 'Fluff Mess Up!', 'Stanton, Matt', NULL, 'The hilarious and unmissable new series about Gilbert, a boy whose best friend is an imaginary giant fluffy bunny called Fluff, from the creator who brought us The Odds, Funny Kid and Bored. Gilbert and Fluff have got themselves into an enormous mess! They have to clean up, but Gilbert would rather not got his hands dirty. What he needs is ... a bunny with a wild idea! A hilarious story full of heart and packed with food fights, jumbo jets, banana smoothies and world domination! From the creator of Funny Kid and The Odds comes the best friend you could ever imagine ... Fluff!', 'verified', '337_fluff_mess_up.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (338, 'Saskia Spark-lee Fundraiser Fail', 'Sharpe Shelberg, Rebecka', NULL, 'Saskia Spark-Lee is back! This time she’s on a mission to save the animals. Saskia Spark-Lee loves animals – she’s almost adopted a whole zoo-worth! But when Da and Dee say they can’t add another to the collection, she must come up with a new plan to continue supporting her furry friends. With some help from Nanna, and the amazing fundraising skills of her friends, Saskia may find where there''s a will there''s a way!', 'verified', '338_saskia_sparklee_fundraiser_fail.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (339, 'To and Fro', 'Clifford-Motopi, Anton', NULL, 'Sam tries to understand what it means to be black in this funny Australian story about identity, family and friendship. Most kids meet their parents when they''re born. All they need to do to impress them is poop, sleep and make goo-goo ga-ga sounds. But I''m twelve. None of that is going to impress my father. Sam thinks he''s a weird-looking white kid with an afro. He lives with his white mum (annoying but not smelly) and brown dog Trevor (smelly but not annoying). He''s never met his father. He just knows that his father is black. But a surprise visit has Sam questioning who he really is. Is he a white kid with a black dad? Or a black kid with white skin? Or half-black and half-white? Not only does Sam want to know these answers, he has to know them to finish his annoying homework and perform in the school concert. But how can he make his outside match his insides if he doesn''t know who he is? A delightfully funny story about family and identity, and what it means to be truly Sam. ''Cheeky, funny and full of heart, To and Fro will have you cheering for Sam right till the end.'' H. Hayek, bestselling author of Huda and Me ''Exuberant, hilarious and messy (just like life!), To and Fro is perfect for kids who feel like their outsides don''t match their insides.'' Rebecca Lim, multi-award-winning author of Tiger Daughter ''Truly satisfying, moving and entertaining. A much-needed novel in Australian children''s literature.'' Emily Gale, award-winning author of The Goodbye Year ''A heartfelt and humorous exploration of the complexities of growing up mixed race in Australia.'' Books+Publishing', 'verified', '339_to_and_fro.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (340, 'Aggie Flea Steals the Show', 'Ingram, Tania', NULL, 'Meet Aggie Flea – She’s a girl with a big imagination ... that lands her in even bigger trouble! The school play is almost here and Aggie wants the role of Web Legs, the superhero spider from Mars! But Aggie’s stage time has always been a disaster! Will she break a leg or break the set?!', 'verified', '340_aggie_flea_steals_the_show.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (341, 'Laughter is the Best Ending', 'Master, Marayam', NULL, 'She likes to read Oscar Wilde and watch documentaries all day which, according to her parents, is not normal for 13 year olds. So they decide to send her on a five-day holiday camp, hoping she''ll make ''at least one friend''. Now, Zee would rather take a bath in Tabasco sauce than attend a camp called Youth Fusion. But with influencer Tiffanee and super-nerds Jonah and Moses, she soon finds herself in the middle of a hair-rising mystery, hurling her into some fierce detective work and bringing her face to face with the notorious Old Bat Viv. LONGLISTED FOR THE AUSTRALIAN BOOK DESIGN AWARDS 2025 BEST DESIGNED CHILDREN''S FICTION BOOK Praise for Laughter is the Best Ending: ''Laugh out loud material, whip smart writing, and meaningful. I had a little cry at the end.'' Karen Foxlee, author of Lenny''s Book of Everything ''I found it so energising! Zee plays with words like a gymnast. We click with her from the very start - she''s funny, frank, fair and feisty! This story will be a hit with young readers.'' Anna Fienberg, author of the Tashi series', 'verified', '341_laughter_is_the_best_ending.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (342, 'Making the Shrine, stories from Victoria''s war memorial', 'Carroll, Laura', NULL, 'A tender and funny graphic novel exploring the soul of a city''s most treasured monument. The Shrine of Remembrance has been an everyday sight in the living memory of all Melbournians. But while everyone knows its purpose, not everyone knows the many stories that have surrounded it for a century. The competition for its design, and the eleventh-hour campaign that forced it into existence. The community enterprise that helped to fund it. The hardship and struggle that came with its creation. Throughout it all, the constant battle to define what it represents to the people of Victoria. This graphic novel is a sequence of stories seeking to explain the meaning of the Shrine across time, both to its architects and supporters, and to the many Victorians who contributed to its creation, and to those who have visited, violated and venerated it since. Some of the stories are individual and intimate; others are public history from the archives. In Laura J. Carroll''s words and pictures, the building''s many lives are brought into focus in new and exciting ways.', 'verified', '342_making_the_shrine_stories_from_victorias_war_memorial.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (343, 'How did I Get Here', 'Philip Bunting', NULL, 'This is the unathorised biography of you. Charting your incredible journey from Big Bang to birth (in about the time it takes to eat your breakfast), Philip Bunting''s hilarious and one of a kind history of evolution was created to raise more questions than it answers. Perfect for fans of Jon Klassen and Chris Haughton.', 'verified', '343_how_did_i_get_here.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (344, 'Babies at the Billabong', 'Maura Finn and Cate James', NULL, 'Journey through the night with some of Australia''s most fascinating furry friends. Meet waddling wombats, bounding bilbies, prancing possums and daring devils in this delightful introduction to our cute and quirky nocturnal marsupials.', 'verified', '344_babies_at_the_billabong.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (345, 'Where the Wild Things Are', 'Maurice Sendak', NULL, 'Max is sent to bed without supper and imagines sailing away to the land of Wild Things, where he is made king. Winner, 1964 Caldecott MedalNotable Children''s Books of 1940-1970 (ALA)1981 Boston Globe-Horn Book Award for Illustration1963, 1982 Fanfare Honor List (The Horn Book)Best Illustrated Children''s Books of 1963, 1982 (NYT)A Reading Rainbow Selection1964 Lewis Carroll Shelf AwardChildren''s Books of 1981 (Library of Congress)1981 Children''s Books (NY Public Library)100 Books for Reading and Sharing 1988 (NY Public Library)', 'verified', '345_where_the_wild_things_are.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (346, 'Press Here', 'Henve'' Tullet', NULL, 'Each page of this surprising book instructs the reader to press the dots, shake the pages, tilt the book, and who knows what will happen next! Children and adults alike will giggle with delight as the dots multiply, change direction, and grow in size, in this unique picture book about the power of imagination and interactivity will provide read-aloud fun for all ages.', 'verified', '346_press_here.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (347, 'This is a ball', 'Beck and Matt Stanton', NULL, '''The kids are having a ball (whoops, having fun) and a discussion is born'' — 4 stars, Good Reading For the Grown-Ups: You know how you''re right all the time? All. The. Time. Yes, well, it''s time to give the kids a turn. Which is why everything you read in this book is going to be wrong. But that''s ok, because the kids are going to correct you. And they''re going to love it! PRAISE FOR THE BOOKS THAT DRIVE KIDS CRAZY SERIES ''Funny, clever, deliciously dry ... this book encourages kids to think outside the square, and hopefully, somewhere deep in that unlimited subconscious, understand that what we see is all about perception. What a powerful thought'' -- Kids'' Book Review ''Witty, silly, and interactive ... A rollicking read for children and adults alike'' -- Kirkus Reviews', 'verified', '347_this_is_a_ball.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (348, 'A Squash and a Squeeze', 'Julia Donaldson Axel', 'Axel Schefier', 'With the help of an old man and all of her animals, an old lady realizes that her house is not as small as she thought it was. Suggested level: preschool, junior.', 'verified', '348_a_squash_and_a_squeeze.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (349, 'The Ugly Five', 'Julia Donaldson', 'Axel Scheffler', 'Meet Wildebeest, Warthog, Spotted Hyena, Lappet-Faced Vulture, and Marabou Stork. On the African savannah, they''re known as the ugly five. But these animals are just as lovable and intriguing as their more celebrated counterparts.', 'verified', '349_the_ugly_five.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (350, 'Bad Dog', 'Mike Boldt', NULL, 'The differences between cats and dogs have never been funnier! In this hilarious story from the illustrator of I Don''t Want to Be a Frog, a little girl really, really wants a dog . . . but gets a cat instead! "Look what I got for my birthday! A pet dog!" says a little girl holding a . . . cat? Rocky doesn''t listen or obey like all the other dogs. (Because Rocky is a cat.) And Rocky hates her leash and doesn''t seem to like other dogs. (Probably because Rocky is a cat.) And rather than play fetch, Rocky prefers to . . . lick between her toes? Ew. Rocky is a bad "dog"! BUT Rocky doesn''t bark, and is so cute when she sleeps in sunny spots. Maybe Rocky IS a good dog? (Or, you know, maybe Rocky is a cat.) Cat lovers and dog lovers alike will howl with laughter at this little girl''s willful insistence that her cat is a dog. The hilarious ways in which cats and dogs are different are brilliantly illuminated with each turn of the page and will leave young readers and their grown-ups giggling. ★ Winner: Missouri Building Block Picture Book Award, 2021 ★ Winner: North Carolina Children''s Book Award, 2022 ★ Winner: Wyoming Library Association Buckaroo Award, 2021-22 ★ Winner: Ontario Library Association Forest of Reading Blue Spruce Award, 2021 ★ Winner: Sakura Medal, Japan, 2022 ★ Nominee: Indiana Early Literacy Firefly Award, 2022', 'verified', '350_bad_dog.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (351, 'The Very Hungry Bear', 'Nick Bland', NULL, 'The Very Cranky Bear is back, and now he''s hungry! When the Very Hungry Bear goes fishing, he ends up catching more than he bargained for - a polar bear, with an armful of fish, who needs help finding a new home! Vibrant illustrations and a fun, engaging story make this book perfect for reading aloud. This is the third book about the delightful and endearing Very Cranky Bear. The Very Cranky Bear was first published in 2008 and has become an international best-seller. Now in board book format - perfect for little hands!', 'verified', '351_the_very_hungry_bear.jpg');
insert into books (source_row, title, author, illustrator, blurb, blurb_status, cover_url) values (352, 'I say ooh, You say Aah', 'John Kane', NULL, 'A madcap call-and-response picture book; this is interactive storytelling at its best. ''There''s something very important that I need you to remember. When I say Ooh, you say Aah. Let''s try it.'' Ooh the donkey has lost his pants. Readers must help him find them! In this picture book, young readers help to tell the story by responding to simple verbal or visual cues. This hilarious book is perfect for reading aloud and is fun for the whole family.', 'verified', '352_i_say_ooh_you_say_aah.jpg');
